#include "test_common.h"
#include "linked_list.h"
static bool match_int(const void*d,const void*k){return *(const int*)d==*(const int*)k;}
static int32_t cmp_int(const void*a,const void*b){int x=*(const int*)a,y=*(const int*)b;return (x>y)-(x<y);}
static void test_list_lifecycle(void){BmsLinkedList_t l;int a=2,b=1,key=2,repl=5;void*f=NULL;ASSERT_STATUS(BMS_STATUS_OK,LinkedListInitialize(&l,sizeof(int)));CU_ASSERT_TRUE(LinkedListIsEmpty(&l));ASSERT_STATUS(BMS_STATUS_OK,LinkedListInsertBack(&l,&a));ASSERT_STATUS(BMS_STATUS_OK,LinkedListInsertFront(&l,&b));CU_ASSERT_EQUAL(LinkedListGetCount(&l),2U);ASSERT_STATUS(BMS_STATUS_OK,LinkedListFind(&l,match_int,&key,&f));CU_ASSERT_EQUAL(*(int*)f,2);ASSERT_STATUS(BMS_STATUS_OK,LinkedListUpdate(&l,match_int,&key,&repl));key=5;ASSERT_STATUS(BMS_STATUS_OK,LinkedListDelete(&l,match_int,&key));CU_ASSERT_EQUAL(LinkedListGetCount(&l),1U);LinkedListClear(&l);CU_ASSERT_TRUE(LinkedListIsEmpty(&l));}
static void test_list_sort(void){BmsLinkedList_t l;int a=3,b=1,c=2;ASSERT_STATUS(BMS_STATUS_OK,LinkedListInitialize(&l,sizeof(int)));LinkedListInsertBack(&l,&a);LinkedListInsertBack(&l,&b);LinkedListInsertBack(&l,&c);ASSERT_STATUS(BMS_STATUS_OK,LinkedListSort(&l,cmp_int));CU_ASSERT_EQUAL(*(int*)l.head->data,1);CU_ASSERT_EQUAL(*(int*)l.tail->data,3);LinkedListClear(&l);}
void RegisterLinkedListTests(void){CU_pSuite s=CU_add_suite("Linked List",NULL,NULL);CU_add_test(s,"lifecycle",test_list_lifecycle);CU_add_test(s,"sort",test_list_sort);}
